-- p01_upgrade, node 1. Generated by gen.py from special/src/p01_upgrade.sql.
-- Usage:  psql -X -q -v ON_ERROR_STOP=1 -d <database> -f p01_upgrade_node1.sql
--
-- Case P1 (also P2, P3): compare a cluster with its copy made by pg_upgrade.
-- Stand: an old cluster and a new cluster of a newer major version.
-- Run:   1. node 1 script in a database of the old cluster (add the main
--           node1.sql there too, for a check of every type);
--        2. stop the old cluster and run pg_upgrade. Use --copy or --clone:
--             pg_upgrade -b <old bin> -B <new bin> -d <old data> -D <new data> --copy
--           With --link the two clusters share their files, and the old one
--           must not be started once the new one has run: there is nothing
--           left to compare with. That is the point of the case: say it in
--           the documentation of the comparison;
--        3. start both clusters on different ports; run the node 2 script in
--           the database of the new cluster: it changes rows after the upgrade;
--        4. compare every table of the two databases.
-- Expect: sp.p01_upgraded: rows 10, 5000 changed, row 9000 only on node 1, row
--         10001 only on node 2; every other table of the database matches.
--         The two servers have different major versions and, most likely,
--         track_commit_timestamp = off: a row read that asks for the commit
--         time of a row fails on such a server (case P2). Tables without a
--         key, foreign tables and views must be listed as not compared, with
--         an exit code that is not zero (case P3).

SET client_min_messages = warning;
SET TimeZone = 'UTC';
SET DateStyle = 'ISO, MDY';
SET IntervalStyle = 'postgres';
SET default_transaction_read_only = off;
CREATE SCHEMA IF NOT EXISTS sp;
DROP TABLE IF EXISTS sp.p01_upgraded;
CREATE TABLE sp.p01_upgraded (id int PRIMARY KEY, v text, f float8, ts timestamptz, j jsonb);
INSERT INTO sp.p01_upgraded SELECT i, 'v' || i, i / 7.0, '2026-01-01 00:00:00+00'::timestamptz + i * interval '1 minute', jsonb_build_object('n', i, 'x', i / 3.0)
	FROM generate_series(1, 10000) i;
COMMENT ON TABLE sp.p01_upgraded IS 'P1: after the steps of the header: 2 changed rows, 1 row only on node 1, 1 row only on node 2';
